{
  "components": [
    {
      "type": "claim",
      "quote": "The SFOE determines whether a project concerning a transmission line with a nominal voltage of 220 kV or higher has to be specified in a sectoral plan (verification of a sectoral plan requirement).",
      "gist": "SFOE decides if a high-voltage transmission line project needs sectoral plan specification."
    },
    {
      "type": "entity",
      "quote": "SFOE",
      "gist": "Swiss Federal Office of Energy"
    },
    {
      "type": "entity",
      "quote": "Federal Inspectorate for Heavy Current Installations",
      "gist": "Swiss authority for high-voltage installations"
    },
    {
      "type": "obligation",
      "quote": "The SFOE may request appropriate documentation from the applicant.",
      "gist": "SFOE can ask for project documentation from the applicant."
    },
    {
      "type": "condition",
      "quote": "If it can be assumed that the project will not have any significant spatial or environmental impacts, it is not subject to the sectoral plan requirement.",
      "gist": "Project exempt from sectoral plan if no significant spatial or environmental impacts expected."
    }
  ]
}
